package ch.bbw.zork;import ch.bbw.zork.Items.Item;import ch.bbw.zork.enums.Direction;import ch.bbw.zork.enums.FurnitureData;import ch.bbw.zork.enums.RoomData;import ch.bbw.zork.enums.RoomShape;import ch.bbw.zork.interfaces.Uncover;import java.util.*;import static ch.bbw.zork.Constants.*;/** * Author:  Michael Kolling, Version: 1.1, Date: August 2000 * refactoring: Rinaldo Lanza, September 2020 */public class Room {    private final String name;    private final String description;	private int x;    private int y;    private final RoomShape roomShape;    private final HashSet<Direction> doorFrames;    private HashMap<Direction, Door> doors;    private final RoomData roomData;    private final House house;    private ArrayList<Furniture> furnitureList;    private Furniture floor;    private HashSet<Furniture> scannedFurniture;    private HashSet<Item> scannedFloorItems;    private boolean discovered;    public Room(int x, int y, RoomData data, House house) {        this(data, house);        this.x = x;        this.y = y;    }    public Room(RoomData data, House house) {        this.house = house;        this.name = data.getName();        this.description = data.getDescription();        this.furnitureList = new ArrayList<>();        this.roomData = data;        this.doorFrames = new HashSet<>();        this.doorFrames.addAll(Arrays.asList(data.getDoorFrames()));        this.roomShape = data.getShape();        this.doors = new HashMap<>();        this.floor = new Furniture(FurnitureData.FLOOR);        this.scannedFurniture = null;        this.scannedFloorItems = null;        this.discovered = false;    }    public RoomShape getRoomShape() {        return roomShape;    }    public Set<Direction> getDoorFrames() {        return doorFrames;    }    public String getName() {        return name;    }    public String getDescription() {        return description;    }    public int getX() {        return x;    }    public int getY() {        return y;    }    public void setY(int y) {        this.y = y;    }    public void setX(int x) {        this.x = x;    }    public boolean isDiscovered() {        return discovered;    }    public void addFurniture(FurnitureData furnitureData) {        addFurniture(new Furniture(furnitureData));    }    public void addFurniture(Furniture furniture) {        this.furnitureList.add(furniture);    }    public ArrayList<Furniture> getFurnitureList() {        return furnitureList;    }    public int getFurnitureCount(FurnitureData furnitureData) {        int count = 0;        for (Furniture furniture : furnitureList) {            if (furniture.getFurnitureData().equals(furnitureData)) {                count++;            }        }        return count;    }    public void dropItemOnFloor(Item item) {        this.floor.getContainer().stashItem(item);    }    public Item takeItemFromFloor(String itemID) {        return this.floor.getContainer().fetchItem(itemID);    }    public void addDoor(Direction dir, Door door) {        this.doors.put(dir, door);    }    public Door getDoor(Direction dir) {        return this.doors.get(dir);    }    public void removeDoorFrame(Direction dir) {        if (!this.doorFrames.contains(dir)) {            return;        }        if (this.doors.get(dir) != null) {           throw new RuntimeException("Cannot remove door frame!");        }        this.doorFrames.remove(dir);    }    public String[] getMapPiece() {        boolean playerInRoom = house.getPlayerLocation() == this;        String[] mapPiece = new String[ROOM_HEIGHT];        if (this.doorFrames.contains(Direction.NORTH)) {            Door northDoor = (this.doors.get(Direction.NORTH));            if (northDoor != null && northDoor.isLocked()) {                mapPiece[0] = HORIZONTAL_WALL_LOCKED_DOOR;            }            else {                mapPiece[0] = HORIZONTAL_WALL_OPEN_DOOR;            }        }        else {            mapPiece[0] = HORIZONTAL_WALL_PLAIN;        }        if (this.doorFrames.contains(Direction.SOUTH)) {            Door southDoor = (this.doors.get(Direction.SOUTH));            if (southDoor != null && southDoor.isLocked()) {                mapPiece[mapPiece.length-1] = HORIZONTAL_WALL_LOCKED_DOOR;            }            else {                mapPiece[mapPiece.length-1] = HORIZONTAL_WALL_OPEN_DOOR;            }        }        else {            mapPiece[mapPiece.length-1] = HORIZONTAL_WALL_PLAIN;        }        char eastDoorChar = WALL_CHAR;        if (this.doorFrames.contains(Direction.EAST)) {            Door eastDoor = (this.doors.get(Direction.EAST));            if (eastDoor != null && eastDoor.isLocked()) {                eastDoorChar = DOOR_LOCKED_CHAR;            }            else {                eastDoorChar = DOOR_OPEN_CHAR;            }        }        char westDoorChar = WALL_CHAR;        if (this.doorFrames.contains(Direction.WEST)) {            Door westDoor = (this.doors.get(Direction.WEST));            if (westDoor != null && westDoor.isLocked()) {                westDoorChar = DOOR_LOCKED_CHAR;            }            else {                westDoorChar = DOOR_OPEN_CHAR;            }        }        for (int i = 1; i < mapPiece.length-1; i++) {            if (ROOM_NAME_LINE - 1 == i) {                mapPiece[i] = FLOOR_LINE(westDoorChar, eastDoorChar);            } else if (ROOM_NAME_LINE == i) {                mapPiece[i] = FLOOR_LINE(westDoorChar, eastDoorChar, this.getName());            } else if (PLAYER_LINE == i && playerInRoom) {                mapPiece[i] = FLOOR_LINE(westDoorChar, eastDoorChar, PLAYER_CHAR);            } else {                mapPiece[i] = FLOOR_LINE(WALL_CHAR, WALL_CHAR);            }        }        return mapPiece;    }    public int getDepthScore() {        if (this.getRoomData() == RoomData.FRONT_YARD) {            return 0;        }        int score = 0;        for (Direction dir : doors.keySet()) {            Room neighbor = house.findRoomByCoordinates(house.getNeighborCoordinates(x, y, dir));            score = Math.min(score, neighbor.getDepthScore());        }        return score+1;    }    public RoomData decideNeighbor(Direction dir) {        if (!this.doorFrames.contains(dir)) {            throw new RuntimeException("No DoorFrame to the specified direction exists");        }        int[] coordinates = house.getNeighborCoordinates(x, y, dir);        ArrayList<RoomData> candidates = house.getCandidatesForCoodinates(coordinates);        for (RoomData rd : ROOM_DATA_LIST) {            Direction[] doorFrames = rd.getDoorFrames();            if (!Arrays.asList(doorFrames).contains(dir.getOpposite()) || (!Objects.equals(rd.getName(), "Corridor") && house.getUsedRoomTypes().contains(rd))) {                candidates.remove(rd);            }        }        if (candidates.size() > 1) {            int index = Game.getRandom().nextInt(candidates.size());            return candidates.get(index);        }        else if (candidates.isEmpty()) {            return null;        }        return candidates.get(0);    }    public RoomData getRoomData() {        return roomData;    }    public HashSet<Furniture> getScannedFurniture() {        return scannedFurniture;    }    public HashSet<Item> getScannedFloorItems() {        return scannedFloorItems;    }    public ArrayList<Direction> getMissingNeighborDirections() {        ArrayList<Direction> missing = new ArrayList<>();        for (Direction dir : doorFrames) {            int[] coords = house.getNeighborCoordinates(x, y, dir);            if (house.findRoomByCoordinates(coords[0], coords[1]) == null) {                missing.add(dir);            }        }        return missing;    }    public void hideItem(Item hiddenItem) {        int furnitureIndex = 0;        ArrayList<Furniture> hidingSpots = new ArrayList<>(this.furnitureList);        while (!hidingSpots.isEmpty()) {            furnitureIndex = Game.getRandom().nextInt(hidingSpots.size());            Furniture candidate = hidingSpots.get(furnitureIndex);            HashMap<String, Container> storage = candidate.getStorage();            FurnitureData furnitureData = candidate.getFurnitureData();            ArrayList<String> containerNames = furnitureData.getContainerNames();            if (storage.isEmpty()) {                hidingSpots.remove(furnitureIndex);            }            else {                int containerIndex = Game.getRandom().nextInt(storage.keySet().size());                String containerName = containerNames.get(containerIndex);                Container container = candidate.getStorage().get(containerName);                container.stashItem(hiddenItem);                return;            }        }        throw new RuntimeException("Cannot hide this item.");    }    public void enter() {        System.out.printf("You enter the %s\n", this.name);        this.discovered = true;    }    public void firstEnter() {        this.discovered = true;    }    public void scan() {        ArrayList<Uncover> uncovers = Game.getPlayer().getAllUncovers();        ArrayList<Furniture> furnitureList = getUncoveredFurniture(uncovers);        ArrayList<Item> itemList = getUncoveredFloorItems(uncovers);        this.scannedFurniture = new HashSet<>();        this.scannedFloorItems = new HashSet<>();        this.scannedFurniture.addAll(furnitureList);        this.scannedFloorItems.addAll(itemList);    }    public ArrayList<Furniture> getUncoveredFurniture(ArrayList<Uncover> uncover) {        ArrayList<Furniture> uncoveredFurniture = new ArrayList<>();        for (Furniture furniture : furnitureList) {            if (furniture.tryUncover(uncover)) {                uncoveredFurniture.add(furniture);            }        }        return uncoveredFurniture;    }    public ArrayList<Item> getUncoveredFloorItems(ArrayList<Uncover> uncovers) {        return this.floor.getContainer().check(uncovers);    }    @Override    public String toString() {        return String.format("%s:\n\tNorth: %s\n\tEast: %s\n\tSouth: %s\n\tWest: %s",                this.getName(),                this.getDoor(Direction.NORTH) == null,                this.getDoor(Direction.EAST) == null,                this.getDoor(Direction.SOUTH) == null,                this.getDoor(Direction.WEST) == null);    }}